import difflib

orig_lines = [l.strip() for l in orig_text.split('\n') if l.strip()]
draft_lines = [l.strip() for l in rewrite_draft.split('\n') if l.strip()]

print("=== CHECKING FOR EXACT SENTENCE / PHRASE MATCHES ===")

# Check author bio specifically:
bio = "Sophia Shkuro is a content manager from Dnipro, Ukraine. Believes that the more complex a thing is, the easier it should be to write about it. Dreams of a future vacation by the sea."
