# Check all phrases of length >= 6 words
orig_words = re.findall(r'\b[\w\'-]+\b', orig_text)
draft_words = re.findall(r'\b[\w\'-]+\b', rewrite_draft)

def get_word_ngrams(words, n=6):
    return [tuple(words[i:i+n]) for i in range(len(words)-n+1)]

orig_6grams = set(get_word_ngrams([w.lower() for w in orig_words], 6))
draft_6grams = get_word_ngrams([w.lower() for w in draft_words], 6)

matching_6grams = []
for i, gram in enumerate(draft_6grams):
    if gram in orig_6grams:
        matching_6grams.append((" ".join(gram), i))

print(f"\nTotal 6-gram matches: {len(matching_6grams)}")
for gram, idx in matching_6grams:
    print(f"  Match at idx {idx}: '{gram}'")
